package regression

import (
	"context"
	"fmt"
	"path/filepath"
	"strings"
)

// MiSTerSSHConfigRunner adds an externally-managed OpenSSH config file to the
// argv generated by MiSTerSSHRemote. It is intentionally a thin argv adapter:
// credentials and config contents never enter regression progress or logs.
type MiSTerSSHConfigRunner struct {
	Base MiSTerCommandRunner
	Path string
}

func (r MiSTerSSHConfigRunner) Run(ctx context.Context, program string, args, env []string, input []byte, maxOutput int) ([]byte, error) {
	if r.Base == nil || !filepath.IsAbs(r.Path) || strings.ContainsAny(r.Path, "\x00\r\n") {
		return nil, fmt.Errorf("MiSTer SSH config runner requires a runner and absolute config path")
	}
	args = append([]string(nil), args...)
	base := filepath.Base(program)
	if base == "sshpass" {
		if len(args) < 2 || args[0] != "-e" || filepath.Base(args[1]) != "ssh" && filepath.Base(args[1]) != "scp" {
			return nil, fmt.Errorf("sshpass command does not wrap a supported OpenSSH client")
		}
		args = removeSSHPortOverride(args, 2, filepath.Base(args[1]) == "scp")
		args = insertSSHConfigArg(args, 2, r.Path)
	} else if base == "ssh" || base == "scp" {
		args = removeSSHPortOverride(args, 0, base == "scp")
		args = insertSSHConfigArg(args, 0, r.Path)
	} else {
		return nil, fmt.Errorf("unsupported MiSTer transport executable %q", base)
	}
	return r.Base.Run(ctx, program, args, env, input, maxOutput)
}

// The board's external OpenSSH config is authoritative for its port. The
// generic remote transport emits its default port explicitly, which would
// otherwise override that file's Port directive.
func removeSSHPortOverride(args []string, start int, scp bool) []string {
	flag := "-p"
	if scp {
		flag = "-P"
	}
	result := append([]string(nil), args[:start]...)
	for i := start; i < len(args); i++ {
		if args[i] == flag {
			i++
			continue
		}
		result = append(result, args[i])
	}
	return result
}

func insertSSHConfigArg(args []string, at int, config string) []string {
	result := make([]string, 0, len(args)+2)
	result = append(result, args[:at]...)
	result = append(result, "-F", config)
	result = append(result, args[at:]...)
	return result
}
